import sys

def lca(x, y):
    if x > y:
        return lca(y, x)
    while y > x:
        y //= 2
    return x

def distance(i, j):
    l = lca(i, j)
    return (i - l) + (j - l)

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    queries = [(int(data[2*i+1]), int(data[2*i+2])) for i in range(N)]

    results = [distance(i, j) for i, j in queries]

    for result in results:
